<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Offer extends Model { protected $guarded=[]; protected $casts=['expires_at'=>'date','is_promotion'=>'boolean','is_active'=>'boolean','price'=>'decimal:2','old_price'=>'decimal:2']; public function medicine(){return $this->belongsTo(Medicine::class);} public function organization(){return $this->belongsTo(Organization::class);} public function effectivePrice(): float{return (float)($this->old_price && $this->old_price > $this->price ? $this->price : $this->price);} }
